changeSet.sql:
create or alter procedure [graph].[UpdateAssetEdge] @uid uniqueidentifier as begin if exists (select 1 from graph.AssetEdge where [uid] = @uid) and not exists (select 1 from [Intersect] where [uid] = @uid) begin delete from graph.AssetEdge where [uid] = @uid end else if exists (select 1 from graph.AssetEdge where [uid] = @uid) begin declare @subjectUid uniqueidentifier, @objectUid uniqueidentifier, @currentSubjectUid uniqueidentifier, @currentObjectUid uniqueidentifier;
select @subjectUid = S.[uid], @objectUid = T.[uid] from graph.AssetNode S, graph.AssetEdge E, graph.AssetNode T where MATCH(S-(E)->T) and E.[uid] = @uid;
select @currentSubjectUid = SubjectUid, @currentObjectUid = ObjectUid from [IntersectDetail] I where I.[uid] = @uid;
if (@subjectUid <> @currentSubjectUid or @objectUid <> @currentObjectUid) begin --recreate edge record since subject or object has changed delete from graph.AssetEdge where [uid] = @uid;
insert into graph.AssetEdge ($from_id, $to_id, ID, Uid, IntersectTypeID, IntersectTypeUid, PredicateID, PredicateUid, PredicateType, Properties, [State], UpdatedOn) select SG.$node_id, OG.$node_id, I.ID, I.[Uid], T.ID as IntersectTypeID, T.[Uid] as IntersectTypeUid, P.ID as PredicateID, P.Uid as PredicateUid, P.Type as PredicateType, '<props/>' as Properties, I.[State], coalesce(I.UpdatedOn, I.CreatedOn, getutcdate()) as UpdatedOn from [Intersect] I inner join Asset SA on SA.[Object] = I.[Subject] and SA.ObjectID = I.SubjectID inner join graph.AssetNode SG on SG.ID = SA.ID inner join Asset OA on OA.[Object] = I.[Object] and OA.ObjectID = I.ObjectID inner join graph.AssetNode OG on OG.ID = OA.ID inner join IntersectType T on T.ID = I.IntersectTypeID inner join [Predicate] P on P.ID = T.PredicateID where I.[uid] = @uid and not exists (select 1 from graph.AssetEdge where [uid] = @uid) end else begin update E set E.UpdatedOn = I.UpdatedOn, E.IntersectTypeID = I.IntersectTypeID, E.IntersectTypeUid = T.[Uid], E.PredicateID = T.PredicateID, E.PredicateUid = P.[Uid], E.PredicateType = P.[Type], E.[State] = I.[State] from graph.AssetEdge E inner join [Intersect] I on I.ID = E.ID inner join IntersectType T on T.ID = I.IntersectTypeID inner join [Predicate] P on P.ID = T.PredicateID where I.[uid] = @uid; end end else begin insert into graph.AssetEdge ($from_id, $to_id, ID, Uid, IntersectTypeID, IntersectTypeUid, PredicateID, PredicateUid, PredicateType, Properties, [State], UpdatedOn) select SG.$node_id, OG.$node_id, I.ID, I.[Uid], T.ID as IntersectTypeID, T.[Uid] as IntersectTypeUid, P.ID as PredicateID, P.Uid as PredicateUid, P.Type as PredicateType, '<props/>' as Properties, I.[State], coalesce(I.UpdatedOn, I.CreatedOn, getutcdate()) as UpdatedOn from [Intersect] I inner join Asset SA on SA.[Object] = I.[Subject] and SA.ObjectID = I.SubjectID inner join graph.AssetNode SG on SG.ID = SA.ID inner join Asset OA on OA.[Object] = I.[Object] and OA.ObjectID = I.ObjectID inner join graph.AssetNode OG on OG.ID = OA.ID inner join IntersectType T on T.ID = I.IntersectTypeID inner join [Predicate] P on P.ID = T.PredicateID where I.[uid] = @uid and not exists (select 1 from graph.AssetEdge where [uid] = @uid) end end
